import type {
  CanvasNodeInteractionState,
  CanvasNodeVisualStatusTone,
} from "@workspace/ui/components/canvas-node/canvas-node";
import type { ReactNode } from "react";

export interface EntryNodeStates {
  /** Human-facing Resource Display Name; falls back to `name` when absent. */
  displayName?: string;
  name: string;
}

export type EntryNodeTargetStatusTone =
  | "accessible"
  | "degraded"
  | "inaccessible"
  | "not-configured"
  | "progressing"
  | "unknown"
  | (string & {});

export interface EntryNodeTargetStatus {
  label: string;
  tone?: EntryNodeTargetStatusTone;
  visualTone?: CanvasNodeVisualStatusTone;
}

/** One Public Address row: the hostname shown, the full URL copied/opened. */
export interface EntryNodeAddress {
  /** Hostname drawn in the row (or a placeholder such as "Pending"). */
  host: string;
  /**
   * Trailing part of `host` drawn de-emphasised — the platform suffix
   * (`.sealos.run`) that every Platform Address shares.
   */
  hostSuffix?: string;
  id?: string;
  status?: EntryNodeTargetStatus;
  /** Full URL for copy and open; absent while the address is pending. */
  value?: string;
}

/** Public Addresses that reach one App Listening Port, headed by its name. */
export interface EntryNodeGroup {
  addresses: EntryNodeAddress[];
  /** Port Display Name; absent ports are headed by their number alone. */
  name?: string;
  port: number;
}

/**
 * What the header's Open control opens: the Default Open Port's best Public
 * Address. `url` absent means the control is drawn disabled with
 * `disabledReason` (or the default "Not accessible yet").
 */
export interface EntryNodeOpenTarget {
  disabledReason?: string;
  /** "Open <Port Display Name>", or "Open" for an unnamed port. */
  label: string;
  url?: string;
}

export type EntryNodeAddressKey = string;

export type EntryNodeCopyAddressHandler = (
  address: EntryNodeAddress,
  key: EntryNodeAddressKey
) => Promise<void> | void;

export interface EntryNodeState {
  copiedAddressKey?: EntryNodeAddressKey | null;
  groups?: EntryNodeGroup[];
  /** Absent when the AP has no Public Address to open. */
  open?: EntryNodeOpenTarget;
  states: EntryNodeStates;
}

export interface EntryNodeActions {
  copyAddress?: EntryNodeCopyAddressHandler;
}

export interface EntryNodeMeta {
  copiedFeedbackMs?: number;
}

export interface EntryNodeContextValue {
  actions: EntryNodeActions;
  meta: EntryNodeMeta;
  state: EntryNodeState;
}

export interface EntryNodeProviderProps {
  children?: ReactNode;
  value: EntryNodeContextValue;
}

export interface EntryNodeRootProps {
  children?: ReactNode;
  copiedAddressKey?: EntryNodeAddressKey | null;
  copiedFeedbackMs?: number;
  defaultExpanded?: boolean;
  expanded?: boolean;
  groups?: EntryNodeGroup[];
  interaction?: CanvasNodeInteractionState;
  onCopyAddress?: EntryNodeCopyAddressHandler;
  onExpandedChange?: (expanded: boolean) => void;
  open?: EntryNodeOpenTarget;
  states: EntryNodeStates;
}

"use client";

import { createContext, use } from "react";

import type { EntryNodeContextValue } from "./entry-node.types";

export const EntryNodeContext = createContext<EntryNodeContextValue | null>(
  null
);

export function useEntryNode(): EntryNodeContextValue {
  const value = use(EntryNodeContext);

  if (!value) {
    throw new Error(
      "EntryNode: compound components must be used within EntryNode.Root"
    );
  }

  return value;
}

"use client";

import { EntryNodeContext } from "./entry-node.context";
import type { EntryNodeProviderProps } from "./entry-node.types";

export function EntryNodeProvider({ children, value }: EntryNodeProviderProps) {
  return <EntryNodeContext value={value}>{children}</EntryNodeContext>;
}

"use client";

import {
  CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS,
  CanvasNodeCopyFeedbackScope,
} from "@workspace/ui/components/canvas-node/canvas-node.copyable-row";
import { CanvasNodeRoot } from "@workspace/ui/components/canvas-node/canvas-node.root";

import { EntryNodeProvider } from "./entry-node.provider";
import type {
  EntryNodeAddressKey,
  EntryNodeContextValue,
  EntryNodeRootProps,
} from "./entry-node.types";

export function EntryNodeRoot({
  children,
  copiedAddressKey,
  copiedFeedbackMs = CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS,
  defaultExpanded,
  expanded,
  groups,
  interaction,
  onCopyAddress,
  onExpandedChange,
  open,
  states,
}: EntryNodeRootProps) {
  return (
    <CanvasNodeRoot
      defaultExpanded={defaultExpanded}
      expanded={expanded}
      interaction={interaction}
      onExpandedChange={onExpandedChange}
    >
      <CanvasNodeCopyFeedbackScope
        copiedFeedbackMs={copiedFeedbackMs}
        copiedKey={copiedAddressKey}
      >
        {({ copiedKey }) => {
          const value: EntryNodeContextValue = {
            actions: {
              copyAddress: onCopyAddress,
            },
            meta: {
              copiedFeedbackMs,
            },
            state: {
              copiedAddressKey: copiedKey as EntryNodeAddressKey | null,
              groups,
              open,
              states,
            },
          };

          return (
            <EntryNodeProvider value={value}>{children}</EntryNodeProvider>
          );
        }}
      </CanvasNodeCopyFeedbackScope>
    </CanvasNodeRoot>
  );
}

"use client";

import { AppIconButton } from "@workspace/ui/components/app-icon-button";
import { CanvasNode } from "@workspace/ui/components/canvas-node/canvas-node";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@workspace/ui/components/tooltip";
import { cn } from "@workspace/ui/lib/utils";
import { ExternalLink, Router } from "lucide-react";
import type { SyntheticEvent } from "react";

import { useEntryNode } from "./entry-node.context";
import { EntryNodeGroupList } from "./entry-node.group";
import {
  entryNodeAddresses,
  resolveEntryNodeGroupsStatus,
} from "./entry-node.status";
import type { EntryNodeOpenTarget } from "./entry-node.types";

export const ENTRY_NODE_LABEL = "Public access";
export const ENTRY_NODE_OPEN_LABEL = "Open";
export const ENTRY_NODE_OPEN_NOT_ACCESSIBLE_REASON = "Not accessible yet";
export const ENTRY_NODE_OPEN_NOT_CONFIGURED_REASON = "Not configured";

export function entryNodeAddressCountLabel(count: number): string {
  return count === 1 ? "1 address" : `${count} addresses`;
}

/**
 * Why the Open control is disabled, or undefined when it opens `open.url`.
 * No target at all means the AP has no Public Address; a target without a
 * URL means none of the Default Open Port's addresses is accessible yet.
 */
export function entryNodeOpenDisabledReason(
  open: EntryNodeOpenTarget | undefined
): string | undefined {
  if (open === undefined) {
    return ENTRY_NODE_OPEN_NOT_CONFIGURED_REASON;
  }
  if (open.url === undefined || open.url.trim() === "") {
    return open.disabledReason ?? ENTRY_NODE_OPEN_NOT_ACCESSIBLE_REASON;
  }
  return undefined;
}

function useEntryNodeResolvedStatus() {
  const {
    state: { groups },
  } = useEntryNode();

  return resolveEntryNodeGroupsStatus(groups);
}

function stopNodeEvent(event: SyntheticEvent) {
  event.stopPropagation();
}

export function EntryNodeContent() {
  return (
    <CanvasNode.Card>
      <CanvasNode.Header>
        <EntryNodeHeaderContent />
      </CanvasNode.Header>
      <CanvasNode.Body>
        <EntryNodeGroupList />
      </CanvasNode.Body>
    </CanvasNode.Card>
  );
}

/**
 * Header: label + address count on the left, the Open control on the right.
 * No per-address health is aggregated here (CONTEXT.md, AP Public Access
 * Node); the rows carry their own status dots.
 */
export function EntryNodeHeaderContent({ className }: { className?: string }) {
  return (
    <div className={cn("canvas-node-header-content min-w-0 flex-1", className)}>
      <div className="flex min-w-0 items-center justify-between gap-1.5">
        <EntryNodeAccess />
        <EntryNodeOpen />
      </div>
    </div>
  );
}

export function EntryNodeAccess({ className }: { className?: string }) {
  const {
    state: { groups },
  } = useEntryNode();
  const addressCount = entryNodeAddresses(groups).length;
  const Icon = Router;

  return (
    <span className={cn("flex min-w-0 flex-1 items-center gap-1.5", className)}>
      <span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-white/5">
        <Icon aria-hidden className="size-4 text-zinc-50" />
      </span>
      <span className="flex min-w-0 flex-1 flex-col gap-1.5">
        <span className="min-w-0 truncate font-normal text-sm text-zinc-50 leading-5">
          {ENTRY_NODE_LABEL}
        </span>
        <span
          className="min-w-0 truncate font-normal text-muted-foreground text-xs leading-4"
          data-slot="entry-node-address-count"
        >
          {entryNodeAddressCountLabel(addressCount)}
        </span>
      </span>
    </span>
  );
}

/**
 * The one Open control of the node: an anchor-backed icon button that opens
 * the Default Open Port's best Public Address in a new tab. Without a URL it
 * stays visible but disabled, and its tooltip carries the reason. Visible in
 * the collapsed node too, so the card is always one click from the app.
 */
export function EntryNodeOpen({ className }: { className?: string }) {
  const {
    state: { open },
  } = useEntryNode();
  const label = open?.label ?? ENTRY_NODE_OPEN_LABEL;
  const disabledReason = entryNodeOpenDisabledReason(open);
  const url = disabledReason === undefined ? open?.url : undefined;
  const button = (
    <AppIconButton
      aria-description={disabledReason}
      aria-disabled={disabledReason === undefined ? undefined : true}
      aria-label={label}
      className={cn(
        "nodrag nopan shrink-0 cursor-pointer border-0",
        disabledReason !== undefined &&
          "cursor-not-allowed opacity-50 hover:text-brand-primary-foreground",
        className
      )}
      data-slot="entry-node-open"
      nativeButton={url === undefined ? undefined : false}
      onClick={stopNodeEvent}
      onDoubleClick={stopNodeEvent}
      onKeyDown={stopNodeEvent}
      onPointerDown={stopNodeEvent}
      render={
        url === undefined ? undefined : (
          // biome-ignore lint/a11y/useAnchorContent: Base UI merges the button children into the anchor
          <a href={url} rel="noopener noreferrer" target="_blank" />
        )
      }
      size="md"
      type="button"
      variant="node"
    >
      <ExternalLink aria-hidden className="size-4" />
    </AppIconButton>
  );

  return (
    <Tooltip>
      <TooltipTrigger render={button} />
      <TooltipContent>{disabledReason ?? label}</TooltipContent>
    </Tooltip>
  );
}

/** Aggregate health pill. No longer part of the header; kept for callers. */
export function EntryNodeStatus({ className }: { className?: string }) {
  const status = useEntryNodeResolvedStatus();

  return <CanvasNode.Status className={className} status={status} />;
}

import type {
  CanvasNodeStatus,
  CanvasNodeVisualStatusTone,
} from "@workspace/ui/components/canvas-node/canvas-node";

import type {
  EntryNodeAddress,
  EntryNodeGroup,
  EntryNodeTargetStatus,
} from "./entry-node.types";

type EntryNodeTargetStatusBucket =
  | "accessible"
  | "failed"
  | "neutral"
  | "progressing"
  | "warning";

const ACCESSIBLE_TONES = new Set([
  "accessible",
  "available",
  "bound",
  "complete",
  "ready",
  "running",
  "succeeded",
]);

const PROGRESSING_TONES = new Set([
  "binding",
  "creating",
  "pending",
  "progressing",
]);

const WARNING_TONES = new Set(["degraded", "deleting", "stopping"]);

const FAILED_TONES = new Set(["error", "failed", "inaccessible", "unhealthy"]);

const NEUTRAL_TONES = new Set([
  "not-configured",
  "shutdown",
  "stopped",
  "unknown",
]);

function normalizeEntryNodeTargetTone(input: string | undefined) {
  return input
    ?.trim()
    .toLowerCase()
    .replace(/[\s_]+/g, "-");
}

function getBucketForVisualTone(
  visualTone: CanvasNodeVisualStatusTone | undefined
): EntryNodeTargetStatusBucket | undefined {
  switch (visualTone) {
    case "positive":
      return "accessible";
    case "progress":
      return "progressing";
    case "warning":
      return "warning";
    case "negative":
      return "failed";
    case "neutral":
      return "neutral";
    default:
      return undefined;
  }
}

function getVisualToneForBucket(
  bucket: EntryNodeTargetStatusBucket
): CanvasNodeVisualStatusTone {
  switch (bucket) {
    case "accessible":
      return "positive";
    case "progressing":
      return "progress";
    case "warning":
      return "warning";
    case "failed":
      return "negative";
    case "neutral":
      return "neutral";
    default:
      return "neutral";
  }
}

function resolveTargetBucket(
  status: EntryNodeTargetStatus | undefined
): EntryNodeTargetStatusBucket {
  const visualBucket = getBucketForVisualTone(status?.visualTone);

  if (visualBucket) {
    return visualBucket;
  }

  const tone = normalizeEntryNodeTargetTone(status?.tone ?? status?.label);

  if (tone && ACCESSIBLE_TONES.has(tone)) {
    return "accessible";
  }

  if (tone && PROGRESSING_TONES.has(tone)) {
    return "progressing";
  }

  if (tone && WARNING_TONES.has(tone)) {
    return "warning";
  }

  if (tone && FAILED_TONES.has(tone)) {
    return "failed";
  }

  if (tone && NEUTRAL_TONES.has(tone)) {
    return "neutral";
  }

  return "neutral";
}

export function resolveEntryNodeTargetVisualStatus(
  status: EntryNodeTargetStatus | undefined
): CanvasNodeStatus {
  const bucket = resolveTargetBucket(status);

  return {
    label: status?.label?.trim() || "Unknown",
    visualTone: getVisualToneForBucket(bucket),
  };
}

function everyTone(
  buckets: EntryNodeTargetStatusBucket[],
  bucket: EntryNodeTargetStatusBucket
) {
  return buckets.every((item) => item === bucket);
}

/** Aggregate health of every address on the node, regardless of grouping. */
export function resolveEntryNodeTargetStatus(
  addresses: readonly Pick<EntryNodeAddress, "status">[] | undefined
): CanvasNodeStatus {
  if (!addresses || addresses.length === 0) {
    return { label: "Not configured", visualTone: "neutral" };
  }

  const buckets = addresses.map((address) =>
    resolveTargetBucket(address.status)
  );

  if (everyTone(buckets, "accessible")) {
    return { label: "Accessible", visualTone: "positive" };
  }

  if (everyTone(buckets, "progressing")) {
    return { label: "Progressing", visualTone: "progress" };
  }

  if (everyTone(buckets, "failed")) {
    return { label: "Inaccessible", visualTone: "negative" };
  }

  if (everyTone(buckets, "neutral")) {
    return { label: "Not configured", visualTone: "neutral" };
  }

  return { label: "Degraded", visualTone: "warning" };
}

export function entryNodeAddresses(
  groups: readonly EntryNodeGroup[] | undefined
): EntryNodeAddress[] {
  return (groups ?? []).flatMap((group) => group.addresses);
}

export function resolveEntryNodeGroupsStatus(
  groups: readonly EntryNodeGroup[] | undefined
): CanvasNodeStatus {
  return resolveEntryNodeTargetStatus(entryNodeAddresses(groups));
}

"use client";

import { CanvasNode } from "@workspace/ui/components/canvas-node/canvas-node";
import { cn } from "@workspace/ui/lib/utils";

import { useEntryNode } from "./entry-node.context";
import { resolveEntryNodeTargetVisualStatus } from "./entry-node.status";
import type { EntryNodeAddress, EntryNodeGroup } from "./entry-node.types";

function getAddressKey(
  group: EntryNodeGroup,
  address: EntryNodeAddress,
  index: number
) {
  return address.id ?? `${group.port}-${index}`;
}

/**
 * A group header is drawn whenever there is something to tell apart: more
 * than one port, or a single port that carries a name. A lone unnamed port
 * draws none, so single-port APs look exactly as before.
 */
export function entryNodeShowsGroupHeaders(
  groups: readonly EntryNodeGroup[]
): boolean {
  return groups.length > 1 || groups.some((group) => group.name !== undefined);
}

export function EntryNodeGroupList({ className }: { className?: string }) {
  const {
    state: { groups = [] },
  } = useEntryNode();
  const populated = groups.filter((group) => group.addresses.length > 0);

  if (populated.length === 0) {
    return (
      <div
        className={cn(
          "entry-node-target-empty mt-2.5 flex min-w-0 items-center rounded-lg bg-zinc-950/20 px-2.5 text-muted-foreground text-xs leading-4",
          className
        )}
        data-slot="entry-node-target-empty"
      >
        Not configured
      </div>
    );
  }

  const showHeaders = entryNodeShowsGroupHeaders(populated);

  return (
    <div
      className={cn(
        "entry-node-group-list mt-2.5 flex min-w-0 flex-col gap-1.5",
        className
      )}
      data-slot="entry-node-group-list"
    >
      {populated.map((group) => (
        <EntryNodeGroupBlock
          group={group}
          key={group.port}
          showHeader={showHeaders}
        />
      ))}
    </div>
  );
}

export function EntryNodeGroupBlock({
  className,
  group,
  showHeader,
}: {
  className?: string;
  group: EntryNodeGroup;
  showHeader: boolean;
}) {
  return (
    <div
      className={cn(
        "entry-node-group flex min-w-0 flex-col gap-0.5 rounded-lg bg-zinc-950/20 p-1",
        className
      )}
      data-slot="entry-node-group"
    >
      {showHeader ? (
        <div
          className="flex min-w-0 items-baseline gap-1.5 px-2 pt-1 pb-0.5 text-xs leading-4"
          data-slot="entry-node-group-header"
        >
          {group.name === undefined ? null : (
            <span className="min-w-0 truncate text-zinc-50">{group.name}</span>
          )}
          <span className="shrink-0 font-mono text-muted-foreground">
            :{group.port}
          </span>
        </div>
      ) : null}
      {group.addresses.map((address, index) => {
        const rowKey = getAddressKey(group, address, index);
        return (
          <EntryNodeAddressRow address={address} key={rowKey} rowKey={rowKey} />
        );
      })}
    </div>
  );
}

export function EntryNodeHostText({
  className,
  host,
  hostSuffix,
}: Pick<EntryNodeAddress, "host" | "hostSuffix"> & { className?: string }) {
  const suffix =
    hostSuffix !== undefined &&
    hostSuffix !== "" &&
    host.length > hostSuffix.length &&
    host.endsWith(hostSuffix)
      ? hostSuffix
      : undefined;

  if (suffix === undefined) {
    return <span className={cn("min-w-0 truncate", className)}>{host}</span>;
  }

  return (
    <span className={cn("flex min-w-0 items-baseline", className)}>
      <span className="shrink-0">{host.slice(0, -suffix.length)}</span>
      <span
        className="min-w-0 truncate text-muted-foreground"
        data-slot="entry-node-host-suffix"
      >
        {suffix}
      </span>
    </span>
  );
}

export function EntryNodeAddressRow({
  address,
  className,
  rowKey,
}: {
  address: EntryNodeAddress;
  className?: string;
  rowKey: string;
}) {
  const { actions } = useEntryNode();
  const visualStatus = resolveEntryNodeTargetVisualStatus(address.status);
  const value = address.value?.trim() ?? "";
  const copyable = value !== "";

  return (
    <CanvasNode.CopyableRow
      className={cn(
        "entry-node-address-row relative flex min-w-0 items-center gap-2 rounded-md px-2 py-1.5 transition-colors",
        copyable && "hover:bg-white/5",
        className
      )}
      copyAriaLabel={`Copy ${value}`}
      copyable={copyable}
      copyValue={value}
      data-slot="entry-node-address-row"
      onCopy={
        actions.copyAddress
          ? () => actions.copyAddress?.(address, rowKey)
          : undefined
      }
      rowKey={rowKey}
      title={copyable ? value : undefined}
    >
      <div className="entry-node-address-content pointer-events-none relative z-10 flex min-w-0 flex-1 items-center gap-1.5 text-xs text-zinc-50 leading-4">
        <CanvasNode.StatusDot size="small" status={visualStatus} />
        <CanvasNode.CopyableRowValue
          className="flex min-w-0 flex-1"
          href={copyable ? value : undefined}
        >
          <EntryNodeHostText
            host={address.host}
            hostSuffix={address.hostSuffix}
          />
        </CanvasNode.CopyableRowValue>
        <CanvasNode.CopyableRowActions label={value} />
      </div>
    </CanvasNode.CopyableRow>
  );
}

"use client";

import "./entry-node.css";

import {
  EntryNodeAccess,
  EntryNodeContent,
  EntryNodeHeaderContent,
  EntryNodeOpen,
  EntryNodeStatus,
} from "./entry-node.content";
import {
  EntryNodeAddressRow,
  EntryNodeGroupBlock,
  EntryNodeGroupList,
  EntryNodeHostText,
} from "./entry-node.group";
import { EntryNodeRoot } from "./entry-node.root";

// biome-ignore lint/performance/noBarrelFile: compound hook re-export for `import { useEntryNode }`
export {
  ENTRY_NODE_LABEL,
  ENTRY_NODE_OPEN_LABEL,
  ENTRY_NODE_OPEN_NOT_ACCESSIBLE_REASON,
  ENTRY_NODE_OPEN_NOT_CONFIGURED_REASON,
  entryNodeAddressCountLabel,
  entryNodeOpenDisabledReason,
} from "./entry-node.content";
export { useEntryNode } from "./entry-node.context";
export { entryNodeShowsGroupHeaders } from "./entry-node.group";
export {
  entryNodeAddresses,
  resolveEntryNodeGroupsStatus,
  resolveEntryNodeTargetStatus,
  resolveEntryNodeTargetVisualStatus,
} from "./entry-node.status";
export type {
  EntryNodeActions,
  EntryNodeAddress,
  EntryNodeAddressKey,
  EntryNodeContextValue,
  EntryNodeCopyAddressHandler,
  EntryNodeGroup,
  EntryNodeMeta,
  EntryNodeOpenTarget,
  EntryNodeProviderProps,
  EntryNodeRootProps,
  EntryNodeState,
  EntryNodeStates,
  EntryNodeTargetStatus,
  EntryNodeTargetStatusTone,
} from "./entry-node.types";
export const EntryNode = {
  Access: EntryNodeAccess,
  AddressRow: EntryNodeAddressRow,
  Content: EntryNodeContent,
  Group: EntryNodeGroupBlock,
  GroupList: EntryNodeGroupList,
  HeaderContent: EntryNodeHeaderContent,
  HostText: EntryNodeHostText,
  Open: EntryNodeOpen,
  Root: EntryNodeRoot,
  Status: EntryNodeStatus,
} as const;

const dn = (component: object, name: string) => {
  (component as { displayName?: string }).displayName = name;
};

dn(EntryNodeRoot, "EntryNode.Root");
dn(EntryNodeContent, "EntryNode.Content");
dn(EntryNodeHeaderContent, "EntryNode.HeaderContent");
dn(EntryNodeAccess, "EntryNode.Access");
dn(EntryNodeOpen, "EntryNode.Open");
dn(EntryNodeStatus, "EntryNode.Status");
dn(EntryNodeGroupList, "EntryNode.GroupList");
dn(EntryNodeGroupBlock, "EntryNode.Group");
dn(EntryNodeAddressRow, "EntryNode.AddressRow");
dn(EntryNodeHostText, "EntryNode.HostText");
